  input  [`TINYRV2_INST_NBITS-1:0]        inst,

  // Packed fields

  output [`TINYRV2_INST_OPCODE_NBITS-1:0] opcode,
  output [`TINYRV2_INST_RD_NBITS-1:0]     rd,
  output [`TINYRV2_INST_RS1_NBITS-1:0]    rs1,
