  assign rd       = inst[`TINYRV2_INST_RD];
  assign rs1      = inst[`TINYRV2_INST_RS1];
  assign rs2      = inst[`TINYRV2_INST_RS2];
  assign funct3   = inst[`TINYRV2_INST_FUNCT3];
